from itertools import combinations

def find_golomb_ruler(marks, fixed_assignments=None):
    if fixed_assignments is None:
        fixed_assignments = {}
    for attempt in range(10000):
        ruler = [0]
        for i in range(1, marks):
            if i in fixed_assignments:
                ruler.append(fixed_assignments[i])
            else:
                ruler.append(attempt)
        distances = set()
        for i, j in combinations(range(marks), 2):
            distance = abs(ruler[i] - ruler[j])
            if distance in distances:
                break
            distances.add(distance)
        else:
            return ruler
    return "UNSATISFIABLE"

print(find_golomb_ruler(7, {1: 2}))
